class Solution {
public:
    int minPairSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n / 2; i++) {
            int s = nums[i] + nums[n - 1 - i];
            if (s > ans) ans = s;
        }
        return ans;
    }
};
